type Entering = { node: HTMLElement; menu: string | null; way: Way | null };

function hostFor(host: HTMLElement) {
  if (getComputedStyle(host).position === 'static' || positioned.has(host)) {
    positioned.add(host);
    host.style.position = 'relative';
