  const style = getComputedStyle(el);
  const sum = (...names: string[]) =>
    style.boxSizing === 'border-box'
      ? 0
      : names.reduce(
          (total, name) =>
            total + (parseFloat(style.getPropertyValue(name)) || 0),
          0,
